"""Export the catalog to ui/viewer/catalog.js so the viewer can use it (works from file:// too).

    python seeder/export_catalog.py
"""
from __future__ import annotations

import json
from pathlib import Path

import catalog as cat

OUT = Path(__file__).parent.parent / "ui" / "viewer" / "catalog.js"


def main():
    catalog = cat.load_catalog()
    errors = cat.validate(catalog)
    if errors:
        raise SystemExit("Catalog errors:\n  - " + "\n  - ".join(errors))
    body = json.dumps(catalog, indent=1)
    OUT.write_text(
        "// Generated by seeder/export_catalog.py from seeder/catalog/*.json. Do not edit by hand.\n"
        "(function (g) {\n  var CATALOG = " + body.replace("\n", "\n  ") + ";\n"
        "  g.CATALOG = CATALOG;\n  if (typeof module !== 'undefined') module.exports = CATALOG;\n"
        "})(typeof window !== 'undefined' ? window : globalThis);\n",
        encoding="utf-8",
    )
    print("Wrote %s (%d modules, %d platforms)" % (OUT, len(catalog["modules"]), len(catalog["platforms"])))


if __name__ == "__main__":
    main()
